#[contracterror]
#[derive(Copy,Clone,Debug,Eq,PartialEq)]
#[repr(u32)]
pub enum Error{
 Initialized=901,Missing=902,Unauthorized=903,Topology=904,Paused=905,Mature=906,Stale=907,
 Deadline=908,Slippage=909,Custody=910,Reentry=911,Balance=912,Invalid=913,
}
#[contracttype]
#[derive(Clone)]
enum Key{Config,State,Busy,Balance(Address)}
const TTL:u32=518_400;
#[contract]
pub struct MarketPoolContract;
fn config(e:&Env)->MarketConfig{e.storage().instance().get(&Key::Config).unwrap_or_else(||panic_with_error!(e,Error::Missing))}
fn state(e:&Env)->MarketState{e.storage().instance().get(&Key::State).unwrap_or_else(||panic_with_error!(e,Error::Missing))}
fn save(e:&Env,s:&MarketState){e.storage().instance().set(&Key::State,s);e.storage().instance().extend_ttl(TTL,TTL);}
fn balance(e:&Env,a:&Address)->i128{e.storage().persistent().get(&Key::Balance(a.clone())).unwrap_or(0)}
fn put_balance(e:&Env,a:&Address,n:i128){let k=Key::Balance(a.clone());e.storage().persistent().set(&k,&n);e.storage().persistent().extend_ttl(&k,TTL,TTL);}
fn enter(e:&Env){if e.storage().instance().get(&Key::Busy).unwrap_or(false){panic_with_error!(e,Error::Reentry)}e.storage().instance().set(&Key::Busy,&true);}
fn leave(e:&Env){e.storage().instance().set(&Key::Busy,&false);}
fn custody(e:&Env,c:&MarketConfig,s:&MarketState){
 let me=e.current_contract_address();
 if PtClient::new(e,&c.pt).balance(&me)<s.reserve_pt||SyClient::new(e,&c.sy).balance_of(&me)<add(e,s.reserve_sy,add(e,s.fee_sy,s.creator_sy)){panic_with_error!(e,Error::Custody)}
}
fn permitted(e:&Env,c:&MarketConfig,a:&Address){
 if !token::StellarAssetClient::new(e,&c.underlying).authorized(a)||!PermClient::new(e,&c.permissioning).is_allowed(a){panic_with_error!(e,Error::Unauthorized)}
}
fn lp_permitted(e:&Env,c:&MarketConfig,a:&Address){
 permitted(e,c,a);
 if !PermClient::new(e,&c.permissioning).is_allowed_for_asset(a,&e.current_contract_address()){panic_with_error!(e,Error::Unauthorized)}
}
fn deadline(e:&Env,d:u64){if e.ledger().timestamp()>d{panic_with_error!(e,Error::Deadline)}}
fn live(e:&Env,c:&MarketConfig,s:&MarketState){
 if s.paused||RiskClient::new(e,&c.risk).is_paused(){panic_with_error!(e,Error::Paused)}
 if e.ledger().timestamp()>=c.maturity{panic_with_error!(e,Error::Mature)}
 permitted(e,c,&e.current_contract_address());custody(e,c,s);
}
fn frame(e:&Env,c:&MarketConfig,s:&MarketState,lp:i128)->CurveFrame{
 let now=e.ledger().timestamp();
 let oracle=OracleClient::new(e,&c.oracle);
 if !oracle.is_fresh(&3600){panic_with_error!(e,Error::Stale)}
 math::frame(e,now,s.started_at,c.maturity,oracle.get_reference_value(),SyClient::new(e,&c.sy).exchange_rate(),c.anchor_apr,c.strength,lp)
}
fn take_pt(e:&Env,c:&MarketConfig,from:&Address,n:i128){
 if n==0{return}let t=PtClient::new(e,&c.pt);let me=e.current_contract_address();let before=t.balance(&me);
 t.transfer(from,&me,&n);if t.balance(&me)!=add(e,before,n){panic_with_error!(e,Error::Custody)}
}
fn take_sy(e:&Env,c:&MarketConfig,from:&Address,n:i128){
 if n==0{return}let t=SyClient::new(e,&c.sy);let me=e.current_contract_address();let before=t.balance_of(&me);
 if t.transfer(from,&me,&n)!=n||t.balance_of(&me)!=add(e,before,n){panic_with_error!(e,Error::Custody)}
}
fn pay(e:&Env,c:&MarketConfig,to:&Address,pt:i128,sy:i128){
 let me=e.current_contract_address();
 if pt>0{let t=PtClient::new(e,&c.pt);let before=t.balance(&me);let recipient=t.balance(to);t.transfer(&me,to,&pt);
 if t.balance(&me)!=sub(e,before,pt)||t.balance(to)!=add(e,recipient,pt){panic_with_error!(e,Error::Custody)}}
 if sy>0{let t=SyClient::new(e,&c.sy);let before=t.balance_of(&me);let recipient=t.balance_of(to);t.transfer(&me,to,&sy);
 if t.balance_of(&me)!=sub(e,before,sy)||t.balance_of(to)!=add(e,recipient,sy){panic_with_error!(e,Error::Custody)}}
}
#[contractimpl]
impl MarketPoolContract{
 pub fn initialize(e:Env,issuer:Address,c:MarketConfig){
  if e.storage().instance().has(&Key::Config){panic_with_error!(&e,Error::Initialized)}
  issuer.require_auth();c.protocol_receiver.require_auth();if token::StellarAssetClient::new(&e,&c.underlying).admin()!=issuer{panic_with_error!(&e,Error::Unauthorized)}
  let sy=SyClient::new(&e,&c.sy);let pt=PtClient::new(&e,&c.pt);let yt=YtClient::new(&e,&c.yt);let m=ManagerClient::new(&e,&c.manager);
  if c.sy==c.pt||c.sy==c.yt||c.pt==c.yt||c.fee_bps>1000||c.protocol_share_bps>10000||
  sy.underlying_address()!=c.underlying||sy.permissioning_address()!=c.permissioning||sy.recovery_escrow()!=c.escrow||
  pt.underlying_address()!=c.underlying||pt.permissioning_address()!=c.permissioning||pt.recovery_escrow()!=c.escrow||pt.maturity()!=c.maturity||pt.minter()!=c.manager||
  yt.underlying_address()!=c.underlying||yt.permissioning_address()!=c.permissioning||yt.oracle_address()!=c.oracle||yt.maturity()!=c.maturity||yt.minter()!=c.manager||yt.accounting_edition()!=3||
  m.underlying_address()!=c.underlying||m.maturity()!=c.maturity||m.accounting_edition()!=3||
  m.sy_wrapper_address()!=c.sy||m.pt_token_address()!=c.pt||m.yt_token_address()!=c.yt||m.oracle_address()!=c.oracle||m.permissioning_address()!=c.permissioning||
  EscrowClient::new(&e,&c.escrow).underlying_address()!=c.underlying{panic_with_error!(&e,Error::Topology)}
  let s=MarketState{reserve_pt:0,reserve_sy:0,fee_sy:0,creator_sy:0,lp_supply:0,started_at:e.ledger().timestamp(),paused:false};
  frame(&e,&c,&s,1);e.storage().instance().set(&Key::Config,&c);save(&e,&s);
  e.events().publish((symbol_short!("init"),),c);
 }
 pub fn configuration(e:Env)->MarketConfig{config(&e)}
 pub fn reserves(e:Env)->MarketState{state(&e)}
 pub fn market_edition(_e:Env)->u32{1}
 pub fn accounting_edition(_e:Env)->u32{3}
 pub fn underlying_address(e:Env)->Address{config(&e).underlying}
 pub fn recovery_escrow(e:Env)->Address{config(&e).escrow}
 pub fn manager_address(e:Env)->Address{config(&e).manager}
 pub fn balance(e:Env,account:Address)->i128{balance(&e,&account)}
 pub fn total_supply(e:Env)->i128{state(&e).lp_supply}
 pub fn decimals(_e:Env)->u32{4}
 pub fn curve(e:Env)->CurveFrame{let c=config(&e);let s=state(&e);live(&e,&c,&s);frame(&e,&c,&s,s.lp_supply)}
 pub fn quote_swap(e:Env,sy_in:bool,amount_in:i128)->TradeQuote{
  let c=config(&e);let s=state(&e);live(&e,&c,&s);
  math::quote(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,frame(&e,&c,&s,s.lp_supply),sy_in,amount_in,c.fee_bps,c.protocol_share_bps)
 }
 pub fn quote_deposit(e:Env,max_pt:i128,max_sy:i128)->LiquidityQuote{
  let c=config(&e);let s=state(&e);live(&e,&c,&s);
  let q=math::deposit(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,max_pt,max_sy);
  frame(&e,&c,&s,add(&e,s.lp_supply,q.shares));q
 }
 pub fn quote_withdrawal(e:Env,shares:i128)->LiquidityQuote{
  let s=state(&e);math::withdrawal(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,shares)
 }
 pub fn swap(e:Env,from:Address,sy_in:bool,amount_in:i128,min_out:i128,expires:u64)->TradeQuote{
  from.require_auth();deadline(&e,expires);if min_out<0{panic_with_error!(&e,Error::Invalid)}enter(&e);
  let c=config(&e);let mut s=state(&e);live(&e,&c,&s);permitted(&e,&c,&from);
  let q=math::quote(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,frame(&e,&c,&s,s.lp_supply),sy_in,amount_in,c.fee_bps,c.protocol_share_bps);
  if q.amount_out<min_out{panic_with_error!(&e,Error::Slippage)}
  if sy_in{take_sy(&e,&c,&from,amount_in);s.reserve_sy=add(&e,s.reserve_sy,amount_in-q.total_fee);s.fee_sy=add(&e,s.fee_sy,q.protocol_fee);s.creator_sy=add(&e,s.creator_sy,q.creator_fee);s.reserve_pt=sub(&e,s.reserve_pt,q.amount_out);pay(&e,&c,&from,q.amount_out,0);}
  else{take_pt(&e,&c,&from,amount_in);s.reserve_pt=add(&e,s.reserve_pt,amount_in);s.fee_sy=add(&e,s.fee_sy,q.protocol_fee);s.creator_sy=add(&e,s.creator_sy,q.creator_fee);s.reserve_sy=sub(&e,s.reserve_sy,q.gross_amount_out);pay(&e,&c,&from,0,q.amount_out);}
  math::bounded(&e,add(&e,s.fee_sy,s.creator_sy),math::MAX_REAL);
  save(&e,&s);custody(&e,&c,&s);leave(&e);e.events().publish((symbol_short!("swap"),), (from,q.clone()));q
 }
 pub fn add_liquidity(e:Env,from:Address,max_pt:i128,max_sy:i128,min_shares:i128,expires:u64)->LiquidityQuote{
  from.require_auth();deadline(&e,expires);if min_shares<0{panic_with_error!(&e,Error::Invalid)}enter(&e);
  let c=config(&e);let mut s=state(&e);live(&e,&c,&s);permitted(&e,&c,&from);
  let q=math::deposit(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,max_pt,max_sy);
  if q.shares<min_shares{panic_with_error!(&e,Error::Slippage)}let f=frame(&e,&c,&s,add(&e,s.lp_supply,q.shares));
  lp_permitted(&e,&c,&from);let exposure=add(&e,accounting::ceil(&e,q.sy,f.sy_rate,math::SCALE),accounting::ceil(&e,q.pt,math::SCALE,f.oracle_rate));
  RiskClient::new(&e,&c.risk).check_deposit(&e.current_contract_address(),&exposure);
  take_pt(&e,&c,&from,q.pt);take_sy(&e,&c,&from,q.sy);
  s.reserve_pt=add(&e,s.reserve_pt,q.pt);s.reserve_sy=add(&e,s.reserve_sy,q.sy);s.lp_supply=add(&e,s.lp_supply,q.shares);
  put_balance(&e,&from,add(&e,balance(&e,&from),q.shares));save(&e,&s);custody(&e,&c,&s);leave(&e);
  e.events().publish((symbol_short!("deposit"),),(from,q.clone()));q
 }
 pub fn remove_liquidity(e:Env,from:Address,shares:i128,min_pt:i128,min_sy:i128,expires:u64)->LiquidityQuote{
  from.require_auth();deadline(&e,expires);if min_pt<0||min_sy<0{panic_with_error!(&e,Error::Invalid)}enter(&e);
  let c=config(&e);let mut s=state(&e);lp_permitted(&e,&c,&from);permitted(&e,&c,&e.current_contract_address());custody(&e,&c,&s);
  let q=math::withdrawal(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,shares);
  if q.pt<min_pt||q.sy<min_sy{panic_with_error!(&e,Error::Slippage)}
  put_balance(&e,&from,sub(&e,balance(&e,&from),shares));s.lp_supply=sub(&e,s.lp_supply,shares);
  s.reserve_pt=sub(&e,s.reserve_pt,q.pt);s.reserve_sy=sub(&e,s.reserve_sy,q.sy);save(&e,&s);pay(&e,&c,&from,q.pt,q.sy);
  custody(&e,&c,&s);leave(&e);e.events().publish((symbol_short!("withdraw"),),(from,q.clone()));q
 }
 pub fn transfer(e:Env,from:Address,to:Address,amount:i128){
  from.require_auth();math::positive(&e,amount);enter(&e);let c=config(&e);lp_permitted(&e,&c,&from);lp_permitted(&e,&c,&to);
  put_balance(&e,&from,sub(&e,balance(&e,&from),amount));put_balance(&e,&to,add(&e,balance(&e,&to),amount));
  leave(&e);e.events().publish((symbol_short!("lp_xfer"),),(from,to,amount));
 }
 pub fn set_paused(e:Env,issuer:Address,paused:bool){
  issuer.require_auth();enter(&e);let c=config(&e);if token::StellarAssetClient::new(&e,&c.underlying).admin()!=issuer{panic_with_error!(&e,Error::Unauthorized)}
  let mut s=state(&e);s.paused=paused;save(&e,&s);leave(&e);
 }
 /// Creator fees belong to the CURRENT SAC admin, including after rotation.
 pub fn collect_creator_fees(e:Env,issuer:Address)->LiquidityQuote{
  issuer.require_auth();enter(&e);let c=config(&e);
  if token::StellarAssetClient::new(&e,&c.underlying).admin()!=issuer{panic_with_error!(&e,Error::Unauthorized)}
  permitted(&e,&c,&issuer);let mut s=state(&e);custody(&e,&c,&s);
  let q=LiquidityQuote{shares:0,pt:0,sy:s.creator_sy};s.creator_sy=0;save(&e,&s);pay(&e,&c,&issuer,q.pt,q.sy);
  custody(&e,&c,&s);leave(&e);e.events().publish((symbol_short!("creator"),),(issuer,q.clone()));q
 }
 /// Protocol receiver is co-authorized at initialization and immutable in v1.
 pub fn collect_protocol_fees(e:Env,receiver:Address)->LiquidityQuote{
  receiver.require_auth();enter(&e);let c=config(&e);
  if receiver!=c.protocol_receiver{panic_with_error!(&e,Error::Unauthorized)}
  permitted(&e,&c,&receiver);let mut s=state(&e);custody(&e,&c,&s);
  let q=LiquidityQuote{shares:0,pt:0,sy:s.fee_sy};s.fee_sy=0;save(&e,&s);pay(&e,&c,&receiver,q.pt,q.sy);
  custody(&e,&c,&s);leave(&e);e.events().publish((symbol_short!("protocol"),),(receiver,q.clone()));q
 }
 /// Only the fixed original escrow authenticates issuer/deauthorization.
 pub fn seize(e:Env,caller:Address,account:Address,shares:i128)->RecoveryResult{
  caller.require_auth();enter(&e);let c=config(&e);if caller!=c.escrow{panic_with_error!(&e,Error::Unauthorized)}
  let mut s=state(&e);custody(&e,&c,&s);let q=math::withdrawal(&e,s.reserve_pt,s.reserve_sy,s.lp_supply,shares);
  put_balance(&e,&account,sub(&e,balance(&e,&account),shares));s.lp_supply=sub(&e,s.lp_supply,shares);
  s.reserve_pt=sub(&e,s.reserve_pt,q.pt);s.reserve_sy=sub(&e,s.reserve_sy,q.sy);save(&e,&s);pay(&e,&c,&caller,q.pt,0);
  let underlying=if q.sy>0{
   let sy=SyClient::new(&e,&c.sy);let me=e.current_contract_address();
   let asset=token::Client::new(&e,&c.underlying);let before=sy.balance_of(&me);let received=asset.balance(&caller);
   let expected=accounting::floor(&e,q.sy,sy.exchange_rate(),math::SCALE);
   let amount=sy.withdraw(&me,&q.sy,&caller);
   if amount!=expected||sy.balance_of(&me)!=sub(&e,before,q.sy)||asset.balance(&caller)!=add(&e,received,amount){panic_with_error!(&e,Error::Custody)}
   amount
  }else{0};
  custody(&e,&c,&s);leave(&e);let result=RecoveryResult{shares,pt:q.pt,sy:q.sy,underlying};
  e.events().publish((symbol_short!("lp_seize"),),(account,result.clone()));result
 }
}

//! Integer virtual-reserve market edition 1. All quantities are atomic units.
//! LP has four decimals; one initial LP atom represents 1000 deposited PT atoms.
//! Virtual balances are never transferable assets or withdrawal entitlements.
use soroban_sdk::{contracterror,contracttype,panic_with_error,Env};
#[path="../../accounting_math.rs"] mod accounting;
use accounting::{add,floor,ceil};
pub const SCALE:i128=10_000_000;
pub const YEAR:i128=31_536_000;
pub const LP_QUANTUM:i128=1_000;
pub const MAX_REAL:i128=1_000_000_000_000_000_000_000_000_000;
pub const MAX_VIRTUAL:i128=1_000_000_000_000_000_000_000_000_000_000_000_000;
pub const MAX_RATE:i128=1_000_000_000_000_000_000;
pub const MAX_COEFFICIENT:i128=1_000_000_000_000_000_000;
#[contracterror]
#[derive(Copy,Clone,Debug,Eq,PartialEq)]
#[repr(u32)]
pub enum MathError{Invalid=801,Range=802,NoOutput=803,InsufficientReserve=804}
#[contracttype]
#[derive(Clone,Debug,Eq,PartialEq)]
pub struct CurveFrame{
 pub sampled_at:u64,pub remaining:u64,pub oracle_rate:i128,pub sy_rate:i128,
 pub target_price:i128,pub pt_coefficient:i128,pub sy_coefficient:i128,
 pub virtual_pt:i128,pub virtual_sy:i128,
}
#[contracttype]
#[derive(Clone,Debug,Eq,PartialEq)]
pub struct TradeQuote{
 pub sy_in:bool,pub amount_in:i128,pub gross_amount_out:i128,pub amount_out:i128,pub fee_in_sy:bool,pub total_fee:i128,
 pub protocol_fee:i128,pub creator_fee:i128,pub fee_tier_bps:u32,pub reserve_pt:i128,pub reserve_sy:i128,
 pub lp_supply:i128,pub frame:CurveFrame,
}
pub fn bounded(e:&Env,n:i128,limit:i128)->i128{if n<0||n>limit{panic_with_error!(e,MathError::Range)}n}
pub fn positive(e:&Env,n:i128)->i128{if n<=0{panic_with_error!(e,MathError::Invalid)}bounded(e,n,MAX_REAL)}
pub fn frame(e:&Env,now:u64,start:u64,maturity:u64,oracle:i128,sy:i128,apr:i128,strength:u32,lp:i128)->CurveFrame{
 if now<start||now>=maturity||maturity<=start||maturity-start>10*YEAR as u64||
 oracle<=0||oracle>MAX_RATE||sy<=0||sy>MAX_RATE||apr<0||apr>SCALE||
 strength==0||strength>100||lp<=0{panic_with_error!(e,MathError::Invalid)}
 let remaining=maturity-now;
 // PT is original-rate notional: maturity underlying is PT*SCALE/oracle.
 // Floors are conservative and never invert the PT/SY quotation.
 let underlying_price=floor(e,SCALE,SCALE,oracle);
 let sy_price=floor(e,underlying_price,SCALE,sy);
 let discount=add(e,SCALE,ceil(e,apr,remaining as i128,YEAR));
 let target=floor(e,sy_price,SCALE,discount);
 if target<=0{panic_with_error!(e,MathError::Range)}
 // Coefficients, not virtual balances, are rounded. LP scaling is EXACT.
 let a=bounded(e,floor(e,LP_QUANTUM*strength as i128,(maturity-start) as i128,remaining as i128),MAX_COEFFICIENT);
 let b=bounded(e,floor(e,a,target,SCALE),MAX_COEFFICIENT);
 if a==0||b==0{panic_with_error!(e,MathError::Range)}
 let vp=bounded(e,floor(e,lp,a,1),MAX_VIRTUAL);
 let vs=bounded(e,floor(e,lp,b,1),MAX_VIRTUAL);
 CurveFrame{sampled_at:now,remaining,oracle_rate:oracle,sy_rate:sy,target_price:target,pt_coefficient:a,sy_coefficient:b,virtual_pt:vp,virtual_sy:vs}
}
pub fn quote(e:&Env,p:i128,s:i128,lp:i128,f:CurveFrame,sy_in:bool,gross:i128,fee_bps:u32,protocol_share_bps:u32)->TradeQuote{
 positive(e,p);positive(e,s);positive(e,lp);positive(e,gross);
 if fee_bps>1000||protocol_share_bps>10_000{panic_with_error!(e,MathError::Invalid)}
 let time_numerator=fee_bps as i128*f.remaining as i128;
 let (real_in,real_out,virtual_in,virtual_out)=if sy_in{(s,p,f.virtual_sy,f.virtual_pt)}else{(p,s,f.virtual_pt,f.virtual_sy)};
 let x=add(e,real_in,virtual_in);let y=add(e,real_out,virtual_out);
 // Original fee asset is SY in BOTH directions. Buy fee is on SY input;
 // sell fee is on gross SY output. Round only the final SY fee, once.
 let input_fee=if sy_in{ceil(e,gross,time_numerator,10_000*YEAR)}else{0};
 if input_fee>=gross{panic_with_error!(e,MathError::NoOutput)}
 let net_input=gross-input_fee;
 let gross_out=floor(e,net_input,y,add(e,x,net_input));
 let fee=if sy_in{input_fee}else{ceil(e,gross_out,time_numerator,10_000*YEAR)};
 let out=if sy_in{gross_out}else{
  if fee>=gross_out{panic_with_error!(e,MathError::NoOutput)}gross_out-fee
 };
 if out<=0{panic_with_error!(e,MathError::NoOutput)}
 if gross_out>=real_out{panic_with_error!(e,MathError::InsufficientReserve)}
 bounded(e,add(e,real_in,net_input),MAX_REAL);
 let protocol=floor(e,fee,protocol_share_bps as i128,10_000);
 TradeQuote{sy_in,amount_in:gross,gross_amount_out:gross_out,amount_out:out,fee_in_sy:true,total_fee:fee,protocol_fee:protocol,creator_fee:fee-protocol,fee_tier_bps:fee_bps,reserve_pt:p,reserve_sy:s,lp_supply:lp,frame:f}
}
#[contracttype]
#[derive(Clone,Debug,Eq,PartialEq)]
pub struct LiquidityQuote{pub shares:i128,pub pt:i128,pub sy:i128}
pub fn deposit(e:&Env,p:i128,s:i128,lp:i128,max_pt:i128,max_sy:i128)->LiquidityQuote{
 positive(e,max_pt);positive(e,max_sy);
 let (shares,pt,sy)=if lp==0{
  if p!=0||s!=0{panic_with_error!(e,MathError::Invalid)}
  (max_pt/LP_QUANTUM,max_pt,max_sy)
 }else{
  positive(e,p);positive(e,s);positive(e,lp);
  let shares=core::cmp::min(floor(e,max_pt,lp,p),floor(e,max_sy,lp,s));
  (shares,ceil(e,shares,p,lp),ceil(e,shares,s,lp))
 };
 positive(e,shares);bounded(e,add(e,lp,shares),MAX_REAL);
 bounded(e,add(e,p,pt),MAX_REAL);bounded(e,add(e,s,sy),MAX_REAL);
 LiquidityQuote{shares,pt,sy}
}
pub fn withdrawal(e:&Env,p:i128,s:i128,lp:i128,shares:i128)->LiquidityQuote{
 positive(e,shares);positive(e,lp);if shares>lp{panic_with_error!(e,MathError::Invalid)}
 LiquidityQuote{shares,pt:floor(e,shares,p,lp),sy:floor(e,shares,s,lp)}
}

//! OracleAdapter — admin-submitted reference value feed with monotonic timestamps.
//!
//! # Why the reference value is monotonically non-decreasing
//! The entire PT/YT settlement model is built on the assumption that the reference rate only
//! goes up: `YTToken.update_yield_index` is a no-op unless `now_rate > last_rate` ("YT never
//! accrues negative yield"), and `PrincipalManager`'s PT formula (`pt_amount * SCALE /
//! final_rate`) implicitly assumes `final_rate` is at or above the rate at issuance -- if
//! `final_rate` could fall below it, that formula would release *more* underlying than was
//! ever deposited for that PT, a real insolvency path, not just a pricing inaccuracy. This
//! matches the reference asset this protocol targets first (Ondo's USDY, a Treasury-backed,
//! NAV-appreciating token whose per-unit redemption value does not decrease in normal
//! operation) but does not hold for every conceivable "reference value" an oracle could feed
//! in (a genuine market price, which can fall). Given the settlement math above already,
//! silently, assumes non-decreasing, this contract enforces it explicitly rather than leaving
//! it as an unenforced deployment assumption -- found during an audit review.

#![no_std]

use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, symbol_short, Address,
    Env,
};

#[contracterror]
#[derive(Copy, Clone, Debug, PartialEq)]
#[repr(u32)]
pub enum Error {
    AlreadyInitialized = 1,
    Unauthorized = 2,
    InvalidValue = 3,
    TimestampTooOld = 4,
    NotInitialized = 5,
    ValueDecreased = 6,
    InvalidObservation = 7,
}

#[contracttype]
pub enum DataKey {
    Admin,
    Price,
    Timestamp,
    SampleCount,
    Sample(u64),
}

#[contracttype]
#[derive(Clone,Debug,Eq,PartialEq)]
pub struct OracleSample { pub sequence:u64,pub value:i128,pub timestamp:u64,pub observed_at:u64 }

#[contract]
pub struct OracleAdapterContract;

#[contractimpl]
impl OracleAdapterContract {
    pub fn initialize(env: Env, admin: Address) {
        if env.storage().instance().has(&DataKey::Admin) {
            panic_with_error!(&env, Error::AlreadyInitialized);
        }
        admin.require_auth();
        env.storage().instance().set(&DataKey::Admin, &admin);
    }

    /// Update the reference value. `caller` must match the stored admin and must authorize.
    pub fn set_reference_value(env: Env, caller: Address, value: i128, timestamp: u64) {
        caller.require_auth();
        let admin: Address = Self::require_admin(&env);
        if caller != admin {
            panic_with_error!(&env, Error::Unauthorized);
        }
        let observed_at=env.ledger().timestamp();
        if timestamp>observed_at || observed_at-timestamp>3_600 {
            panic_with_error!(&env,Error::InvalidObservation);
        }
        if value <= 0 {
            panic_with_error!(&env, Error::InvalidValue);
        }
        let current_price: i128 = env.storage().instance().get(&DataKey::Price).unwrap_or(0);
        if value < current_price {
            panic_with_error!(&env, Error::ValueDecreased);
        }
        let current_ts: u64 = env
            .storage()
            .instance()
            .get(&DataKey::Timestamp)
            .unwrap_or(0u64);
        if timestamp <= current_ts {
            panic_with_error!(&env, Error::TimestampTooOld);
        }
        env.storage().instance().set(&DataKey::Price, &value);
        env.storage()
            .instance()
            .set(&DataKey::Timestamp, &timestamp);
        let sequence:u64=env.storage().instance().get(&DataKey::SampleCount).unwrap_or(0);
        let sequence=sequence.checked_add(1).unwrap_or_else(||panic_with_error!(&env,Error::InvalidObservation));
        let sample=OracleSample{sequence,value,timestamp,observed_at};
        let key=DataKey::Sample(sequence);
        env.storage().persistent().set(&key,&sample);
        let ttl=env.storage().max_ttl();
        env.storage().persistent().extend_ttl(&key,ttl/2,ttl);
        env.storage().instance().set(&DataKey::SampleCount,&sequence);
        env.events()
            .publish((symbol_short!("ref_set"),), (value, timestamp));
    }

    pub fn get_reference_value(env: Env) -> i128 {
        env.storage()
            .instance()
            .get(&DataKey::Price)
            .unwrap_or_else(|| panic_with_error!(&env, Error::NotInitialized))
    }

    pub fn get_reference_timestamp(env: Env) -> u64 {
        env.storage()
            .instance()
            .get(&DataKey::Timestamp)
            .unwrap_or_else(|| panic_with_error!(&env, Error::NotInitialized))
    }

    /// Returns true when the stored timestamp is within `max_stale_seconds` of the ledger clock.
    /// Uses `env.ledger().timestamp()` — callers cannot manipulate this value.
    pub fn is_fresh(env: Env, max_stale_seconds: u64) -> bool {
        let stored_ts: u64 = env
            .storage()
            .instance()
            .get(&DataKey::Timestamp)
            .unwrap_or(0u64);
        let ledger_ts = env.ledger().timestamp();
        if ledger_ts < stored_ts {
            return false;
        }
        ledger_ts - stored_ts <= max_stale_seconds
    }

    /// Single-step admin transfer: current admin authorizes and immediately names a new admin
    /// (no separate acceptance step from the new admin), matching every other contract's
    /// transfer_admin in this codebase.
    pub fn transfer_admin(env: Env, current_admin: Address, new_admin: Address) {
        current_admin.require_auth();
        let admin: Address = Self::require_admin(&env);
        if current_admin != admin {
            panic_with_error!(&env, Error::Unauthorized);
        }
        env.storage().instance().set(&DataKey::Admin, &new_admin);
        env.events()
            .publish((symbol_short!("adm_xfer"),), (current_admin, new_admin));
    }

    pub fn get_admin(env: Env) -> Address {
        Self::require_admin(&env)
    }

    pub fn sample_count(env:Env)->u64 { env.storage().instance().get(&DataKey::SampleCount).unwrap_or(0) }
    pub fn get_sample(env:Env,sequence:u64)->Option<OracleSample> {
        let key=DataKey::Sample(sequence);
        let result=env.storage().persistent().get(&key);
        if result.is_some() { let ttl=env.storage().max_ttl();env.storage().persistent().extend_ttl(&key,ttl/2,ttl); }
        result
    }
    pub fn first_at_or_after(env:Env,timestamp:u64)->Option<OracleSample> {
        let count=Self::sample_count(env.clone());let mut lo=1u64;let mut hi=count;
        let mut found=None;
        while lo<=hi {
            let mid=lo+(hi-lo)/2;
            let sample=Self::get_sample(env.clone(),mid).unwrap_or_else(||panic_with_error!(&env,Error::NotInitialized));
            if sample.timestamp>=timestamp { found=Some(sample);if mid==1{break}hi=mid-1; }
            else {lo=mid+1;}
        }
        found
    }

    // --- internal helpers ---

    fn require_admin(env: &Env) -> Address {
        env.storage()
            .instance()
            .get(&DataKey::Admin)
            .unwrap_or_else(|| panic_with_error!(env, Error::NotInitialized))
    }
}

#[cfg(test)]
mod test {
    use soroban_sdk::{
        testutils::{Address as _, Ledger as _},
        Address, Env,
    };

    use super::{OracleAdapterContract, OracleAdapterContractClient};

    fn setup() -> (Env, OracleAdapterContractClient<'static>, Address) {
        let env = Env::default();
        env.mock_all_auths();
        env.ledger().with_mut(|li|li.timestamp=1_700_001_000);
        let contract_id = env.register_contract(None, OracleAdapterContract);
        let client = OracleAdapterContractClient::new(&env, &contract_id);
        let admin = Address::generate(&env);
        client.initialize(&admin);
        (env, client, admin)
    }

    #[test]
    fn initialize_and_set_price() {
        let (_env, client, admin) = setup();
        client.set_reference_value(&admin, &103_00000000_i128, &1_700_000_000_u64);
        assert_eq!(client.get_reference_value(), 103_00000000_i128);
        assert_eq!(client.get_reference_timestamp(), 1_700_000_000_u64);
    }

    #[test]
    #[should_panic]
    fn value_decrease_rejected() {
        // The entire PT/YT settlement model assumes the reference rate never falls -- see
        // this module's doc comment for why a decrease must be rejected outright, not just
        // priced in.
        let (_env, client, admin) = setup();
        client.set_reference_value(&admin, &10_300_000_i128, &1_700_000_000_u64);
        client.set_reference_value(&admin, &10_200_000_i128, &1_700_001_000_u64);
    }

    #[test]
    fn value_may_stay_equal() {
        // A resubmission at the same price (e.g. a heartbeat refresh with no real price move)
        // must not be treated as a decrease.
        let (_env, client, admin) = setup();
        client.set_reference_value(&admin, &10_300_000_i128, &1_700_000_000_u64);
        client.set_reference_value(&admin, &10_300_000_i128, &1_700_001_000_u64);
        assert_eq!(client.get_reference_value(), 10_300_000_i128);
    }

    #[test]
    #[should_panic]
    fn double_initialize_panics() {
        let (_env, client, admin) = setup();
        client.initialize(&admin);
    }

    #[test]
    #[should_panic]
    fn unauthorized_price_update_panics() {
        let (env, client, admin) = setup();
        client.set_reference_value(&admin, &103_00000000_i128, &1_700_000_000_u64);
        let attacker = Address::generate(&env);
        client.set_reference_value(&attacker, &200_00000000_i128, &1_700_001_000_u64);
    }

    #[test]
    #[should_panic]
    fn stale_timestamp_rejected() {
        let (_env, client, admin) = setup();
        client.set_reference_value(&admin, &103_00000000_i128, &1_700_000_000_u64);
        client.set_reference_value(&admin, &103_00000000_i128, &1_700_000_000_u64);
    }

    #[test]
    #[should_panic]
    fn invalid_price_rejected() {
        let (_env, client, admin) = setup();
        client.set_reference_value(&admin, &0_i128, &1_700_000_000_u64);
    }

    #[test]
    fn admin_transfer() {
        let (env, client, admin) = setup();
        let new_admin = Address::generate(&env);
        client.transfer_admin(&admin, &new_admin);
        assert_eq!(client.get_admin(), new_admin);
    }

    #[test]
    #[should_panic]
    fn unauthorized_transfer_admin_panics() {
        let (env, client, _admin) = setup();
        let impostor = Address::generate(&env);
        let new_admin = Address::generate(&env);
        client.transfer_admin(&impostor, &new_admin);
    }

    #[test]
    fn is_fresh_within_staleness_window() {
        let (env, client, admin) = setup();
        // Ledger at t=1000; oracle set at t=900 → diff=100 ≤ 3600 → fresh.
        env.ledger().with_mut(|li| li.timestamp = 1_000);
        client.set_reference_value(&admin, &10_300_000_i128, &900_u64);
        assert!(client.is_fresh(&3_600_u64));
    }

    #[test]
    fn is_fresh_false_when_stale() {
        let (env, client, admin) = setup();
        // Ledger at t=1000; oracle set at t=1 → diff=999 > 100 → stale.
        env.ledger().with_mut(|li| li.timestamp = 1_000);
        client.set_reference_value(&admin, &10_300_000_i128, &1_u64);
        assert!(!client.is_fresh(&100_u64));
    }

    #[test]
    fn is_fresh_false_before_any_price_set() {
        let (env, client, _admin) = setup();
        // No price ever set → stored timestamp = 0; ledger = 5000; diff > 3600 → not fresh.
        env.ledger().with_mut(|li| li.timestamp = 5_000);
        assert!(!client.is_fresh(&3_600_u64));
    }

    #[test]
    fn is_fresh_at_exact_boundary() {
        let (env, client, admin) = setup();
        // diff == max_stale_seconds exactly → still fresh (≤ not <).
        env.ledger().with_mut(|li| li.timestamp = 1_000);
        client.set_reference_value(&admin, &10_000_000_i128, &600_u64); // diff = 400
        assert!(client.is_fresh(&400_u64)); // 400 ≤ 400 → fresh
        assert!(!client.is_fresh(&399_u64)); // 400 > 399 → stale
    }

    #[test]
    fn future_source_timestamp_is_rejected() {
        let (env,client,admin)=setup();
        env.ledger().with_mut(|li|li.timestamp=1_000);
        assert!(client.try_set_reference_value(&admin,&10_000_000_i128,&5_000_u64).is_err());
        assert_eq!(client.sample_count(),0);
    }
}

