        f.perm.grant_account(&f.perm_admin, &user);
        f.perm.grant_asset(&f.perm_admin, &user, &f.pt_id);
        token::StellarAssetClient::new(&f.env, &f.underlying).set_authorized(&user, &false);

        f.client.mint(&user, &100);
