    use super::{RecoveryEscrowContract, RecoveryEscrowContractClient};

    const T0: u64 = 1_000;
    const SCALE: i128 = 10_000_000;

    struct Fixture {
        env: Env,
        client: RecoveryEscrowContractClient<'static>,
        sac_admin: Address,
        underlying: Address,
        perm: PermissioningContractClient<'static>,
        perm_admin: Address,
