    // --- share transfer ---

    #[test]
    fn transfer_moves_shares_between_eligible_accounts() {
        let f = setup();
        let user = Address::generate(&f.env);
        let recipient = Address::generate(&f.env);
        grant(&f, &user);
        grant(&f, &recipient);
        mint(&f.env, &f.underlying, &f.admin, &user, 500_000_000);
